def build():
    d = new("legalrisk", subtitle="Правовой анализ и реестр правовых рисков")
    d.h1("ВВЕДЕНИЕ", key="intro")
    d.note("Документ подготовлен ассистентом на основе открытых источников и не является юридической консультацией. Ассистент не юрист. "
           "Перечень рисков предназначен для обсуждения с квалифицированным юристом до публичного запуска сервиса.")
    d.p("Назначение – зафиксировать вопросы, которые не решаются разработкой, и показать, как проектные решения их учитывают. Законодательство меняется; сведения необходимо перепроверить на дату запуска.")
    d.h1("ПРОЕКТНЫЕ РЕШЕНИЯ, ВЛИЯЮЩИЕ НА ПРАВОВОЙ СТАТУС", key="dec")
    d.table("Решения и последствия", ["Решение", "Правовое следствие"], [
        ["Регистрация без телефона и почты", "Конфликт с идентификацией по номеру телефона, если сервис подпадает под соответствующие требования (ПР-01)"],
        ["Обычные чаты технически доступны серверу", "Возможны запросы органов и обязанности по хранению; Соглашение должно прямо об этом говорить (ПР-02, ПР-03, ПР-18)"],
        ["Секретные чаты со сквозным шифрованием", "Сервер не имеет ключей; возможны требования по предоставлению ключей, которые невыполнимы технически (ПР-03)"],
        ["Пользовательский контент", "Распределение ответственности и процедура удаления (ПР-07)"],
        ["Фильтр текста статуса", "Ограничение контента в профиле (ПР-08)"],
        ["Удаление учётной записи с сохранением обезличенных сообщений", "Баланс права на удаление и интересов собеседников (ПР-09)"],
    ], widths=[5.5, 9.0], key="decisions", font=11)
    d.h1("РЕЕСТР ПРАВОВЫХ РИСКОВ", key="reg")
    d.table("Правовые риски", ["Код", "Тема", "Описание", "Уровень", "Меры", "Ответственный"],
            [list(r) for r in RISKS], widths=[1.1, 2.4, 4.0, 1.4, 4.0, 1.6], key="risks", font=9)
    d.h1("НОРМАТИВНАЯ ОСНОВА (ДЛЯ ПРОВЕРКИ ЮРИСТОМ)", key="norm")
    d.bullets([
        "Федеральный закон от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации» (в частности статьи 10.1 и 10.2-1);",
        "Федеральный закон от 27.07.2006 № 152-ФЗ «О персональных данных»;",
        "Гражданский кодекс Российской Федерации (договор присоединения, ответственность);",
        "требования магазинов приложений (RuStore, Google Play, App Store);",
        "при обслуживании пользователей из иных юрисдикций – применимые местные нормы (например, GDPR).",
    ])
    d.h1("ПЕРЕЧЕНЬ ДЕЙСТВИЙ ПЕРЕД ЗАПУСКОМ", key="todo")
    d.numbered([
        "определить оператора сервиса и его реквизиты (ПР-17);",
        "получить юридическое заключение по ПР-01, ПР-02, ПР-03, ПР-11, ПР-18;",
        "выбрать размещение данных с учётом локализации (ПР-04);",
        "утвердить юридические документы (91 01 – 96 01) после проверки юристом;",
        "подать уведомление об обработке ПД при необходимости (ПР-05);",
        "проверить название на товарные знаки (ПР-16);",
        "подготовить материалы для публикации в магазинах (ПР-12).",
    ], style="n")
    return d
